codon_table = {"UUU":"F", "UUC":"F", "UUA":"L", "UUG":"L",
    "UCU":"S", "UCC":"S", "UCA":"S", "UCG":"S",
    "UAU":"Y", "UAC":"Y", "UAA":"STOP", "UAG":"STOP",
    "UGU":"C", "UGC":"C", "UGA":"STOP", "UGG":"W",
    "CUU":"L", "CUC":"L", "CUA":"L", "CUG":"L",
    "CCU":"P", "CCC":"P", "CCA":"P", "CCG":"P",
    "CAU":"H", "CAC":"H", "CAA":"Q", "CAG":"Q",
    "CGU":"R", "CGC":"R", "CGA":"R", "CGG":"R",
    "AUU":"I", "AUC":"I", "AUA":"I", "AUG":"M",
    "ACU":"T", "ACC":"T", "ACA":"T", "ACG":"T",
    "AAU":"N", "AAC":"N", "AAA":"K", "AAG":"K",
    "AGU":"S", "AGC":"S", "AGA":"R", "AGG":"R",
    "GUU":"V", "GUC":"V", "GUA":"V", "GUG":"V",
    "GCU":"A", "GCC":"A", "GCA":"A", "GCG":"A",
    "GAU":"D", "GAC":"D", "GAA":"E", "GAG":"E",
    "GGU":"G", "GGC":"G", "GGA":"G", "GGG":"G"}

def transcribe(dna):
    # print(dna)
    rna_seq = []
    for b in dna:
        if b == "T": rna_seq.append("U")
        else: rna_seq.append(b)
        # print(f"{"-"*i}{codon}{"-"*(len(dna)-i-3)}>{aa}")
    rna_string = "".join(rna_seq)
    # print(rna_string)
    return rna_string

def translation(rna):
    # print(rna)
    peptide_seq = []
    for i in range(0, len(rna)-1, 3):
        codon = rna[i:i+3]
        if len(codon) < 3:
            break
        aa = codon_table[codon]
        if aa == "STOP": 
            break
        else: peptide_seq.append(aa)
        # print(f"{"-"*i}{codon}{"-"*(len(rna)-i-3)}>{aa}")
    peptide_string = "".join(peptide_seq)
    # print(peptide_string)
    return peptide_string

def reverse_complement(dna):
    r_comp = []
    keys = {"A": "T", "T": "A", "C": "G", "G": "C"}
    for b in reversed(dna):
        r_comp.append(keys[b])
    return "".join(r_comp)

def reverse_peptide(pep):
    r_pep = []
    for aa in reversed(pep):
        r_pep.append(aa)
    return "".join(r_pep)

def search_peptides(dna, peptide):
    matches = []
    for i in range(len(dna)-1):
        seq_check = dna[i:i+(len(peptide)*3)]
        pp_or = translation(transcribe(seq_check))
        pp_rc = translation(transcribe(reverse_complement(seq_check)))
        if pp_rc == peptide or pp_or == peptide:
            matches.append(seq_check)
    return matches

